lib='''def background(grid):
    """The most common color in the grid."""
    from collections import Counter
    return Counter(v for row in grid for v in row).most_common(1)[0][0]

def connect_markers(grid, fill=3):
    """Fill background cells lying between consecutive non-background cells in each row and column with fill."""
    h, w = len(grid), len(grid[0])
    bg = background(grid)
    out = [row[:] for row in grid]
    for i in range(h):
        cs = [j for j in range(w) if grid[i][j] != bg]
        for a, b in zip(cs, cs[1:]):
            for j in range(a + 1, b):
                out[i][j] = fill
    for j in range(w):
        rs = [i for i in range(h) if grid[i][j] != bg]
        for a, b in zip(rs, rs[1:]):
            for i in range(a + 1, b):
                out[i][j] = fill
    return out
'''
